INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_1', 'layer_direnis_isci', 'Yolbulan Metal grevi', 'Yer: Dörtyol / Hatay | Sendika/Kurum: Özçelik-İş | İşkolu: Metal | Durum: Devam ediyor | Süre: 20 Haziran 2024 tarihinden beri, 752. gün | Eylem Biçimi: Fabrika önünde grev ve grev nöbeti sürdürülüyor, dayanışma ziyaretleri gerçekleştiriliyor. | Talepler: Yolbulan Metal işçileri, sefalet ücreti dayatmasının son bulmasını, toplu iş sözleşmesinin kendi talepleri doğrultusunda imzalanmasını, insanca ücret ve sosyal hakların güvence altına alınmasını istiyor.', 'POINT', '[36.7878112, 36.2118398]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_2', 'layer_direnis_isci', 'Temel Conta grevi', 'Yer: Kemalpaşa ve Torbalı / İzmir | Sendika/Kurum: Petrol-İş | İşkolu: Petrol, Kimya, Lastik ve Plastik | Durum: Devam ediyor | Süre: 10 Aralık 2024 tarihinden beri, 579. gün | Eylem Biçimi: Grev çadırı kuruluyor, fabrika önünde nöbet tutuluyor, makinelerin taşınmasına karşı fiili takip yapılıyor ve dava süreci izleniyor. | Talepler: Temel Conta işçileri, sendikal yetkinin tanınmasını, toplu iş sözleşmesinin imzalanmasını, ücret ve çalışma koşullarının düzeltilmesini, grev kırıcılığının son bulmasını istiyor.', 'POINT', '[38.4345747, 27.2338065]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_3', 'layer_direnis_isci', 'TÜVTÜRK grevi', 'Yer: İstanbul’daki TÜVTÜRK araç muayene istasyonları | Sendika/Kurum: DİSK/Nakliyat-İş | İşkolu: Ulaştırma ve Araç Muayene | Durum: Devam ediyor | Süre: 13 Aralık 2025 tarihinden beri, 211. gün | Eylem Biçimi: İstasyon önlerinde grev yapılıyor, basın açıklamaları düzenleniyor ve dayanışma ziyaretleri gerçekleştiriliyor. | Talepler: TÜVTÜRK işçileri, işverenin toplu iş sözleşmesi masasına oturmasını, sendikal hakların tanınmasını, sefalet ücreti dayatmasının ve grev kırıcılığının son bulmasını istiyor.', 'POINT', '[41.0914521, 28.5067223]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_4', 'layer_direnis_isci', 'Tapeten Mensucat grevi', 'Yer: Sincan / Ankara | Sendika/Kurum: TEKSİF | İşkolu: Tekstil | Durum: Devam ediyor | Süre: 4 Eylül 2025 tarihinden beri, 311. gün | Eylem Biçimi: Fabrika önünde grev yapılıyor, basın açıklamaları düzenleniyor ve dayanışma ziyaretleri gerçekleştiriliyor. | Talepler: Tapeten Mensucat işçileri, sendikal yetkinin tanınmasını, toplu iş sözleşmesinin imzalanmasını, mobbing ve baskının son bulmasını, hijyen ve çalışma koşullarının düzeltilmesini istiyor.', 'POINT', '[39.9711307, 32.5684525]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_5', 'layer_direnis_isci', 'Colin’s / Eroğlu Moda Tekstil grevi', 'Yer: Avcılar / İstanbul, Tokat ve mağaza önleri | Sendika/Kurum: Öz İplik-İş | İşkolu: Tekstil | Durum: Devam ediyor | Süre: 1 Mayıs 2026 tarihinden beri, 72. gün | Eylem Biçimi: Fabrika önünde grev yapılıyor, mağaza önlerinde eylemler ve basın açıklamaları düzenleniyor. | Talepler: Eroğlu Moda Tekstil işçileri, toplu iş sözleşmesinin kendi talepleri doğrultusunda imzalanmasını, ücret ve sosyal hakların iyileştirilmesini, sendikal haklarının tanınmasını istiyor.', 'POINT', '[41.0085007, 28.7033748]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_6', 'layer_direnis_isci', 'DIGEL Tekstil grevi', 'Yer: Ege Serbest Bölgesi / İzmir | Sendika/Kurum: TEKSİF | İşkolu: Tekstil | Durum: Devam ediyor | Süre: 17 Ocak 2025 tarihinden beri, 541. gün | Eylem Biçimi: Serbest bölge önünde direniş sürdürülüyor, dava süreci takip ediliyor ve dayanışma eylemleri gerçekleştiriliyor. | Talepler: DIGEL Tekstil işçileri, işten atılan işçilerin işe iade edilmesini, sendikal yetkinin tanınmasını, ücret ve çalışma koşullarının düzeltilmesini, mobbing ve baskının son bulmasını istiyor.', 'POINT', '[38.3356357, 27.1194461]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_7', 'layer_direnis_isci', 'Barta Tekstil direnişi', 'Yer: İzmir | Sendika/Kurum: Dev Tekstil | İşkolu: Tekstil | Durum: Devam ediyor | Süre: 7 Nisan 2026 tarihinden beri, 96. gün | Eylem Biçimi: Fabrika önünde nöbet tutuluyor ve basın açıklamaları düzenleniyor. | Talepler: Barta Tekstil işçileri, kod oyunlarıyla tazminatsız işten atılan işçilerin işe iade edilmesini, ücret ve tazminat alacaklarının ödenmesini, sendikal baskının son bulmasını istiyor.', 'POINT', '[38.3126991, 27.1673763]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_8', 'layer_direnis_isci', 'Gezer Tekstil / Gezer Terlik grevi', 'Yer: Bolu ve Esenyurt / İstanbul | Sendika/Kurum: TEKSİF | İşkolu: Tekstil, Deri ve Ayakkabı | Durum: Devam ediyor | Süre: 24 Kasım 2025 tarihinden beri, 230. gün | Eylem Biçimi: Fabrika önünde eylemler yapılıyor, sendikal örgütlenme çalışmaları yürütülüyor ve dava süreci takip ediliyor. | Talepler: Gezer işçileri, sendika düşmanlığının ve işten atmaların son bulmasını, işten atılan işçilerin işe iade edilmesini, ücret ve tazminat alacaklarının ödenmesini istiyor.', 'POINT', '[41.0365611, 28.6256209]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_9', 'layer_direnis_isci', 'Şişli Belediyesi işçileri direnişi', 'Yer: Şişli / İstanbul | Sendika/Kurum: Şişli Belediyesi ve belediye şirket işçileri | İşkolu: Belediye Hizmetleri | Durum: Devam ediyor | Süre: 12 Ocak 2026 tarihinden beri, 181. gün | Eylem Biçimi: Belediye önünde basın açıklamaları, oturma eylemleri ve iş bırakma eylemleri yapılıyor. | Talepler: Şişli Belediyesi işçileri, işten atmaların durdurulmasını, geciken ücretlerin ödenmesini, toplu iş sözleşmesi hükümlerinin uygulanmasını, norm kadro sorununun çözülmesini istiyor.', 'POINT', '[41.0642663, 28.9813495]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_10', 'layer_direnis_isci', 'Turan Çil ve Cem Devran Çiftçi işe iade direnişi', 'Yer: Beşiktaş Belediyesi / İstanbul | Sendika/Kurum: Beşiktaş Belediyesi işçileri | İşkolu: Belediye Hizmetleri | Durum: Devam ediyor | Süre: 16 Aralık 2025 tarihinden beri, 208. gün; 7 Temmuz 2026’da açlık grevine dönüştü | Eylem Biçimi: Belediye önünde direniş sürdürülüyor, basın açıklamaları yapılıyor ve açlık grevi gerçekleştiriliyor. | Talepler: Turan Çil ve Cem Devran Çiftçi, düzensiz ücret ödemelerine itiraz ettikleri için yapılan işten çıkarmaların geri alınmasını, işe iade edilmelerini, ücretlerin düzenli ödenmesini ve iş güvencelerinin sağlanmasını istiyor.', 'POINT', '[41.0748042, 29.0194974]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_11', 'layer_direnis_isci', 'İBB Ağaç AŞ işçileri grevi', 'Yer: İstanbul | Sendika/Kurum: Ağaç ve Peyzaj AŞ işçileri | İşkolu: Belediye Hizmetleri | Durum: Devam ediyor | Süre: 30 Nisan 2026 tarihinden beri, 73. gün; 7 Temmuz 2026’da Merter Ek Hizmet Binası’nda oturma eylemi başladı | Eylem Biçimi: Saraçhane’de ve kurum önünde basın açıklamaları ile oturma eylemleri yapılıyor, dayanışma ziyaretleri gerçekleştiriliyor. | Talepler: İBB Ağaç AŞ işçileri, güvenlik soruşturması gerekçesiyle yapılan işten çıkarmaların geri alınmasını, işten atılan işçilerin işe iade edilmesini, iş güvencesinin sağlanmasını ve ayrımcı uygulamaların son bulmasını istiyor.', 'POINT', '[41.0134947, 28.9552083]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_12', 'layer_direnis_isci', 'Mersin Liman işçileri grevi', 'Yer: Mersin Limanı | Sendika/Kurum: TÜMTİS | İşkolu: Liman, Depolama ve Taşımacılık | Durum: Devam ediyor | Süre: 31 Aralık 2025 tarihinden beri, 193. gün | Eylem Biçimi: Liman kapısı önünde direniş sürdürülüyor, ailelerle birlikte eylemler yapılıyor, adliye önünde ve kamuoyuna yönelik basın açıklamaları düzenleniyor. | Talepler: Mersin Limanı işçileri, işten atılan işçilerin işe iade edilmesini, taşeron düzeninin ve sendikal baskının son bulmasını, iş güvencesi ile sendikal haklarının tanınmasını istiyor.', 'POINT', '[36.7999325, 34.6360452]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_13', 'layer_direnis_isci', 'Bursagaz grevi', 'Yer: Bursa | Sendika/Kurum: DİSK/Enerji-Sen | İşkolu: Enerji | Durum: Devam ediyor | Süre: 10 Haziran 2026 tarihinden beri, 32. gün | Eylem Biçimi: Aksa Doğalgaz Bursa Bölge Müdürlüğü önünde direniş sürdürülüyor, kent eylemleri yapılıyor ve dayanışma çağrıları gerçekleştiriliyor. | Talepler: Bursagaz işçileri, sendikal yetkiye yapılan itirazın geri çekilmesini, toplu iş sözleşmesi sürecinin başlatılmasını, işten atılan 12 işçinin işe iade edilmesini istiyor.', 'POINT', '[40.2326243, 28.9830068]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_14', 'layer_direnis_isci', 'Trendyol Lojistik Denizli grevi', 'Yer: Denizli | Sendika/Kurum: DİSK/İletişim-İş | İşkolu: Depo ve Lojistik | Durum: Devam ediyor | Süre: 16 Haziran 2026 tarihinden beri, 26. gün | Eylem Biçimi: Dağıtım merkezi önünde direniş sürdürülüyor, iş bırakma eylemi ve basın açıklaması yapılıyor. | Talepler: Trendyol Lojistik işçileri, işten atılan işçilerin işe iade edilmesini, prim ve vardiya düzeninin adil biçimde kurulmasını, performans baskısının son bulmasını, mola, terfi ve haberleşme haklarının güvence altına alınmasını istiyor.', 'POINT', '[37.7649404, 29.1012343]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_15', 'layer_direnis_isci', 'Özel sektör öğretmenleri Ankara direnişi', 'Yer: Ankara ve farklı kentler | Sendika/Kurum: Özel Sektör Öğretmenleri Sendikası | İşkolu: Eğitim | Durum: Devam ediyor | Süre: 14 Haziran 2026 tarihinden beri, 28. gün; açlık grevi 13 gün sürdü ve 27 Haziran 2026’da sonlandırıldı | Eylem Biçimi: Ankara buluşması düzenleniyor, MEB önünde eylemler yapılıyor, açlık grevi ve yürüyüş gerçekleştiriliyor. | Talepler: Özel sektör öğretmenleri, taban maaş hakkının tanınmasını, güvenceli çalışma koşullarının sağlanmasını, 10 aylık sözleşme dayatmasının kaldırılmasını, mülakat mağduriyetinin giderilmesini istiyor.', 'POINT', '[39.919619, 32.859601]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_16', 'layer_direnis_kayip', 'Cumartesi Anneleri / İnsanları adalet mücadelesi', 'Yer: Galatasaray Meydanı / İstanbul | Sendika/Kurum: Cumartesi Anneleri / İnsanları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 27 Mayıs 1995 tarihinden beri, 1111.  gün; her cumartesi sürüyor | Eylem Biçimi: Oturma eylemi ve basın açıklaması yapılıyor, davalar ile kayıp dosyaları takip ediliyor. | Talepler: Cumartesi Anneleri ve Cumartesi İnsanları, gözaltında kaybedilenlerin akıbetinin açıklanmasını, faillerin yargılanmasını, cezasızlık politikasının son bulmasını istiyor.', 'POINT', '[41.0333253, 28.9771365]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_17', 'layer_direnis_cinayet', 'Dilovası İşçi Katliamı Davası ve Adalet Nöbeti', 'Yer: Gebze Kent Meydanı / Kocaeli | Sendika/Kurum: Dilovası İşçi Katliamı Aileleri ve DGD-SEN | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 14 Haziran 2026 tarihinden beri, 28. gün; nöbet her pazar sürüyor | Eylem Biçimi: Adalet nöbeti tutuluyor, yürüyüş ve oturma eylemleri yapılıyor, basın açıklamaları düzenleniyor ve duruşmalar takip ediliyor. | Talepler: Dilovası İşçi Katliamı aileleri, 3’ü çocuk 7 işçinin ölümünde patronlar ve kamu görevlileri dahil tüm sorumluların yargılanmasını, cezasızlığın son bulmasını istiyor.', 'POINT', '[40.798966, 29.4307302]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_18', 'layer_direnis_kayip', 'Kartalkaya Grand Kartal Otel İş Cinayeti Davası', 'Yer: Kartalkaya / Bolu | Sendika/Kurum: Kartalkaya katliamında yakınlarını kaybeden aileler ve dava avukatları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 21 Ocak 2025 tarihinden beri, 537. gün; adalet ve dava takibi sürüyor | Eylem Biçimi: Duruşmalar takip ediliyor, adliye önünde basın açıklamaları ve adalet yürüyüşleri düzenleniyor. | Talepler: Kartalkaya’da yakınlarını kaybeden aileler, otel yönetimiyle birlikte denetim ve ruhsat sorumluluğu bulunan tüm kamu görevlilerinin yargılanmasını, cezasızlığın son bulmasını, verilen kararların eksiksiz uygulanmasını istiyor.', 'POINT', '[40.5904287, 31.8072258]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_19', 'layer_direnis_cinayet', 'Hendek Havai Fişek Fabrikası İş Cinayeti Davası', 'Yer: Hendek / Sakarya | Sendika/Kurum: Hendek işçi katliamında yakınlarını kaybeden aileler ve dava avukatları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 3 Temmuz 2020 tarihinden beri, 2200. gün; adalet mücadelesi sürüyor | Eylem Biçimi: Duruşmalar takip ediliyor, fabrika önünde anmalar ve basın açıklamaları yapılıyor. | Talepler: Hendek işçi katliamında yakınlarını kaybeden aileler, fabrika sahipleriyle denetim sorumluluğu bulunan kamu görevlilerinin yargılanmasını, olası kast hükümlerinin uygulanmasını, cezasızlığın son bulmasını istiyor.', 'POINT', '[40.736994, 30.4045448]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_20', 'layer_direnis_cinayet', 'Gayrettepe Gece Kulübü İş Cinayeti Davası', 'Yer: Beşiktaş / İstanbul | Sendika/Kurum: Gayrettepe Katliamı Kayıp Yakınları ve dava avukatları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 2 Nisan 2024 tarihinden beri, 831. gün; dava 30 Ekim 2026’ya ertelendi | Eylem Biçimi: Duruşmalar takip ediliyor, adliye önünde basın açıklamaları yapılıyor ve dayanışma çağrıları gerçekleştiriliyor. | Talepler: Gayrettepe işçi katliamında yakınlarını kaybeden aileler, 29 işçinin ölümünde patronların ve ruhsat ile denetim sorumluluğu bulunan kamu görevlilerinin yargılanmasını, tüm sorumluların ortaya çıkarılmasını, cezasızlığın son bulmasını istiyor.', 'POINT', '[41.065467, 29.008464]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_21', 'layer_direnis_hapishane', 'Kuyu tipi hapishaneler kapatılsın mücadelesi', 'Yer: Türkiye geneli, S tipi, Y tipi ve yüksek güvenlikli hapishaneler | Sendika/Kurum: Mahpuslar, TAYAD’lı Aileler ve hukuk örgütleri | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: Mahpus, hapishane ve eylem türüne göre farklı başlangıç tarihleri bulunuyor | Eylem Biçimi: Açlık grevleri ve ölüm oruçları sürdürülüyor, aile nöbetleri ve basın açıklamaları yapılıyor, dava süreçleri takip ediliyor. | Talepler: Mahpuslar ve aileleri, ağır tecrit ve hücre izolasyonunun kaldırılmasını, görüş ve sosyal hak gasplarının son bulmasını, hasta mahpusların serbest bırakılmasını, kuyu tipi hapishanelerin kapatılmasını istiyor.', 'POINT', '[37.0978579, 27.6485231]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_22', 'layer_direnis_hapishane', 'TAYAD’lı Aileler oturma eylemi', 'Yer: Ankara Kurtuluş Parkı ve Kızılay | Sendika/Kurum: TAYAD’lı Aileler | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 2026’da Ankara Kurtuluş Parkı ve Kızılay’daki dönemsel oturma eylemleri sürüyor | Eylem Biçimi: Oturma eylemi ve basın açıklaması yapılıyor, aile nöbeti tutuluyor. | Talepler: TAYAD’lı Aileler, kuyu tipi hapishanelerin kapatılmasını, tecridin kaldırılmasını, açlık grevindeki ve ölüm orucundaki mahpusların taleplerinin karşılanmasını istiyor.', 'POINT', '[39.9274396, 32.864004]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_23', 'layer_direnis_hapishane', 'Grup Yorum emekçileri açlık grevi', 'Yer: Marmara 6 No’lu L Tipi Hapishanesi / Silivri | Sendika/Kurum: Grup Yorum ve TAYAD’lı Aileler | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 18 Mayıs 2026 tarihinden beri, 55. gün | Eylem Biçimi: Süresiz açlık grevi sürdürülüyor, aileler tarafından açıklamalar yapılıyor ve dayanışma eylemleri gerçekleştiriliyor. | Talepler: Grup Yorum emekçileri ve TAYAD’lı Aileler, tecridin ve hapishane baskılarının son bulmasını, konser yasaklarının kaldırılmasını, tutuklu Grup Yorum üyeleriyle politik tutsakların haklarının tanınmasını istiyor.', 'POINT', '[41.0904287, 28.1520812]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_24', 'layer_direnis_ekoloji', 'Giresun maden direnişi', 'Yer: Görele Karlıbel, Tirebolu Sekü ve Çanakçı / Giresun | Sendika/Kurum: Köylüler ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 4 Nisan 2026 tarihinden beri, 99. gün | Eylem Biçimi: Yollar kesiliyor, iş makineleri durduruluyor, köy nöbeti tutuluyor ve dava süreci takip ediliyor. | Talepler: Görele, Tirebolu ve Çanakçı’daki köylüler, Alagöz Maden’in sondaj ve maden faaliyetlerinin durdurulmasını, su kaynaklarının, fındık bahçelerinin ve yaşam alanlarının korunmasını istiyor.', 'POINT', '[40.853134, 38.894208]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_25', 'layer_direnis_ekoloji', 'Ordu ekoloji mücadelesi', 'Yer: Aybastı, Korgan, Kabataş ve yayla alanları / Ordu | Sendika/Kurum: Köylüler, ekoloji platformları ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: Sürekli ve çok merkezli mücadele; proje ve ilçe bazında başlangıçlar değişiyor | Eylem Biçimi: Halk toplantıları düzenleniyor, yerel platform çalışmaları yürütülüyor ve basın açıklamaları yapılıyor. | Talepler: Ordu’daki köylüler ve yaşam alanı savunucuları, maden, enerji ve turizm projelerinin durdurulmasını, yaylaların, su kaynaklarının, tarım alanlarının ve köy yaşamının korunmasını istiyor.', 'POINT', '[40.7282678, 37.3275148]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_26', 'layer_direnis_ekoloji', 'Akbelen / İkizköy direnişi', 'Yer: Milas / Muğla | Sendika/Kurum: İkizköylüler ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 17 Temmuz 2019 tarihinden beri, 2552. gün; uzun soluklu köy ve orman savunması sürüyor | Eylem Biçimi: Nöbet tutuluyor, dava süreci takip ediliyor, köy savunması sürdürülüyor ve kitlesel eylemler gerçekleştiriliyor. | Talepler: İkizköylüler ve yaşam alanı savunucuları, kömür madeni genişletmesinin durdurulmasını, zeytinliklerin, ormanların ve köy yaşamının korunmasını istiyor.', 'POINT', '[37.1777581, 27.8466806]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_27', 'layer_direnis_ekoloji', 'Varto / Karlıova JES karşıtı mücadele', 'Yer: Varto / Muş ve Karlıova / Bingöl | Sendika/Kurum: Varto Ekoloji Platformu, köylüler ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: Mart 2026’dan beri; gün düzeyinde başlangıç doğrulanamadı | Eylem Biçimi: Direniş nöbeti tutuluyor, miting ve köy toplantıları düzenleniyor, yerel platform çalışmaları yürütülüyor. | Talepler: Varto ve Karlıova’daki köylüler, JES projesinin durdurulmasını, su kaynaklarının, tarımın, hayvancılığın ve köy yaşamının korunmasını istiyor.', 'POINT', '[39.173291, 41.455974]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_28', 'layer_direnis_ekoloji', 'Diyarbakır / Lice ekoloji direnişi', 'Yer: Lice / Diyarbakır | Sendika/Kurum: Yerel halk, kadınlar ve ekoloji savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: Lice ve çevre köylerde proje bazında farklı tarihlerde süren mücadele | Eylem Biçimi: Köylerde açıklamalar yapılıyor, nöbet tutuluyor, dava ve diğer süreçler takip ediliyor. | Talepler: Lice ve çevresindeki halk, maden faaliyetlerinin durdurulmasını, doğa tahribatının ve yaşam alanlarının gasbının son bulmasını, toprağın ve suyun korunmasını istiyor.', 'POINT', '[38.453188, 40.652057]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_29', 'layer_direnis_ekoloji', 'Mardin ekoloji mücadelesi', 'Yer: Mardin ve ilçeleri | Sendika/Kurum: Yerel halk ve ekoloji örgütleri | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: Mardin ve ilçelerinde proje bazında farklı tarihlerde süren mücadele | Eylem Biçimi: Halk toplantıları ve basın açıklamaları düzenleniyor, yerel süreçler takip ediliyor. | Talepler: Mardin’deki halk ve ekoloji örgütleri, maden, taş ocağı ve enerji projelerinin durdurulmasını, tarım alanlarının, su varlıklarının ve yaşam alanlarının korunmasını istiyor.', 'POINT', '[37.3442929, 40.6196487]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_30', 'layer_direnis_ekoloji', 'Mersin Arslanköy / Değirmençay mücadelesi', 'Yer: Toroslar ve Yenişehir / Mersin | Sendika/Kurum: Köylüler, MERÇED ve ekoloji savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 24 Aralık 2025 tarihinden beri, 200. gün | Eylem Biçimi: Halk toplantıları ve basın açıklamaları düzenleniyor, ÇED ve dava süreçleri takip ediliyor. | Talepler: Arslanköy ve Değirmençay’daki köylüler, boksit madeni genişletmesi ile taş ocağı projelerinin durdurulmasını, su kaynaklarının, meraların, tarım alanlarının ve köy yaşamının korunmasını istiyor.', 'POINT', '[37.018431, 34.307207]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_31', 'layer_direnis_ekoloji', 'Şırnak ağaç kesimlerine karşı ekoloji mücadelesi', 'Yer: Besta, Cudi ve Gabar / Şırnak | Sendika/Kurum: Şırnak Ekoloji Derneği, hukukçular ve yerel halk | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: Yıllardır süren, Besta, Cudi ve Gabar’a yayılan çok merkezli mücadele | Eylem Biçimi: Hukuki başvurular yapılıyor, basın açıklamaları ve imza kampanyaları düzenleniyor, ekoloji buluşmaları gerçekleştiriliyor. | Talepler: Şırnak’taki halk ve ekoloji savunucuları, ağaç kesimlerinin, petrol ve maden aramalarının durdurulmasını, ormanların ve yaşam alanlarının korunmasını istiyor.', 'POINT', '[37.328936, 42.1738459]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_32', 'layer_direnis_ekoloji', 'Bingöl ekoloji mücadelesi', 'Yer: Bingöl, özellikle Karlıova | Sendika/Kurum: Köylüler ve ekoloji savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: Bingöl ve Karlıova’da proje bazında farklı tarihlerde süren mücadele | Eylem Biçimi: Köy toplantıları düzenleniyor, yerel platform çalışmaları yürütülüyor ve basın açıklamaları yapılıyor. | Talepler: Bingöl’deki köylüler ve ekoloji savunucuları, JES, maden, HES ve taş ocağı projelerinin durdurulmasını, suyun, toprağın ve köy yaşamının korunmasını istiyor.', 'POINT', '[39.297996, 41.014368]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_33', 'layer_direnis_isci', 'Afyon KYK işçisi işe iade mücadelesi', 'Yer: Destine Hatun Kız Öğrenci Yurdu ve Gençlik ve Spor İl Müdürlüğü önü / Afyonkarahisar | Sendika/Kurum: Tüm Otel ve Turizm İşçileri Sendikası | İşkolu: Konaklama ve Turizm | Durum: Devam ediyor | Süre: 22 Haziran 2026 tarihinden beri, 20. gün | Eylem Biçimi: Gençlik ve Spor İl Müdürlüğü önünde basın açıklaması yapılıyor, işe iade eylemleri ve dayanışma çağrıları gerçekleştiriliyor. | Talepler: OTİS ve işten çıkarılan KYK işçisi, sendikalı işçinin işe iade edilmesini, sendikal baskının son bulmasını, işçi sağlığı ve iş güvenliği önlemlerinin alınmasını istiyor.', 'POINT', '[38.825238, 30.5366968]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_34', 'layer_direnis_isci', 'AFP Türkiye Bürosu grevi', 'Yer: İstanbul | Sendika/Kurum: Türkiye Gazeteciler Sendikası | İşkolu: Basın ve Medya | Durum: Sonuçlandı | Süre: 6 Temmuz 2026 tarihinden beri, 6. gün | Eylem Biçimi: Grev yapılıyor, grev pankartı asılıyor ve basın açıklamaları düzenleniyor. | Talepler: AFP Türkiye Bürosu çalışanları, toplu iş sözleşmesinin kendi talepleri doğrultusunda imzalanmasını, resmi enflasyonun altında kalan zam teklifinin geri çekilmesini, insanca ücretin güvence altına alınmasını istiyor.', 'POINT', '[41.0481956, 28.9954674]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_35', 'layer_direnis_isci', 'Çapa Tıp Fakültesi yemekhane işçileri direnişi', 'Yer: Çapa / Fatih / İstanbul | Sendika/Kurum: DİSK/Gıda-İş ve Çapa yemekhane işçileri | İşkolu: Yemek ve Hizmet | Durum: Devam ediyor | Süre: 10 Temmuz 2026 tarihinden beri, 11. gün | Eylem Biçimi: Hastane yerleşkesinde yürüyüşler ve basın açıklamaları yapılıyor, dayanışma ziyaretleri gerçekleştiriliyor. | Talepler: İşçiler, işten çıkarılanların işe iade edilmesini, geçmiş dönem ücret ve diğer alacakların eksiksiz ödenmesini, ibraname ve sendikadan vazgeçme dayatmalarının kaldırılmasını, sendikalı ve güvenceli çalışma hakkının tanınmasını istiyor.', 'POINT', '[41.0164399, 28.9333376]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_36', 'layer_direnis_isci', 'Eti Gümüş Maden işçileri direnişi', 'Yer: Maden / Elazığ | Sendika/Kurum: Bağımsız Maden İşçileri Sendikası | İşkolu: Maden | Durum: Devam ediyor | Süre: 18 Temmuz 2026 tarihinden beri, 3. gün | Eylem Biçimi: Maden sahasında direniş ve basın açıklamaları yapılıyor; ödeme yapılmaması halinde Ankara yürüyüşü ve mücadelenin büyütülmesi duyuruluyor. | Talepler: İşçiler, 13 aydır ödenmeyen ücret, kıdem ve diğer işçilik alacaklarının eksiksiz ödenmesini, ücretsiz izin dayatmasının son bulmasını istiyor.', 'POINT', '[38.391257, 39.669764]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_37', 'layer_direnis_isci', 'Tatbak işçilerinin sendika ve işe iade mücadelesi', 'Yer: Velibaba / Pendik / İstanbul | Sendika/Kurum: Tekgıda-İş | İşkolu: Gıda | Durum: Devam ediyor | Süre: 14 Temmuz 2026 tarihinden beri, 7. gün | Eylem Biçimi: Fabrika önünde basın açıklamaları ve işe iade eylemleri yapılıyor, dayanışma çağrıları gerçekleştiriliyor. | Talepler: İşçiler, sendikal örgütlenme nedeniyle işten atılan 13 işçinin işe iade edilmesini, baskı ve mobbingin son bulmasını, sendikal yetkinin tanınmasını ve toplu iş sözleşmesi sürecinin başlatılmasını istiyor.', 'POINT', '[40.8956522, 29.2585221]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_38', 'layer_direnis_isci', 'ASSU / Aşkale İçecek grevi', 'Yer: Akyazı / Sakarya | Sendika/Kurum: Öz Gıda-İş | İşkolu: Gıda ve İçecek | Durum: Devam ediyor | Süre: 3 Nisan 2026 tarihinden beri, 109. gün | Eylem Biçimi: Fabrika önünde grev ve grev nöbeti sürdürülüyor, basın açıklamaları ile dayanışma ziyaretleri yapılıyor. | Talepler: İşçiler, işverenin sendikal yetkiyi tanımasını, işten atılan işçilerin işe iade edilmesini, toplu iş sözleşmesinin imzalanmasını ve insanca, güvenli çalışma koşullarını istiyor.', 'POINT', '[40.5748672, 30.8548107]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_39', 'layer_direnis_cinayet', 'Çorlu Tren Katliamı adalet mücadelesi', 'Yer: Sarılar / Çorlu / Tekirdağ | Sendika/Kurum: Çorlu Tren Katliamı aileleri ve dava avukatları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 8 Temmuz 2018 tarihinden beri, 2935. gün | Eylem Biçimi: Dava ve üst yargı süreçleri takip ediliyor, anmalar, yürüyüşler ve basın açıklamaları yapılıyor. | Talepler: Aileler, siyasi ve idari sorumlular dahil bütün kamu görevlilerinin etkili biçimde yargılanmasını, sorumluluğun alt kademe çalışanlarla sınırlandırılmamasını ve cezasızlığın son bulmasını istiyor.', 'POINT', '[41.177635, 27.7784425]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_40', 'layer_direnis_cinayet', 'Amasra Maden İş Cinayeti Davası', 'Yer: Amasra / Bartın | Sendika/Kurum: Amasra maden katliamında yakınlarını kaybeden aileler ve dava avukatları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 14 Ekim 2022 tarihinden beri, 1376. gün | Eylem Biçimi: Duruşma ve istinaf süreçleri takip ediliyor, adliye önünde açıklamalar ve anmalar yapılıyor. | Talepler: Aileler, sorumluların olası kasttan cezalandırılmasını, üst düzey kurum ve kamu yöneticilerinin yargılanmasını, verilen cezaların etkisizleştirilmemesini ve cezasızlığın son bulmasını istiyor.', 'POINT', '[41.74784, 32.385568]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_41', 'layer_direnis_cinayet', 'Soma Maden Katliamı kamu görevlileri davası', 'Yer: Soma / Manisa | Sendika/Kurum: Soma 301 Madenciler Derneği, aileler ve dava avukatları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 13 Mayıs 2014 tarihinden beri, 4452. gün | Eylem Biçimi: Duruşma ve istinaf süreçleri takip ediliyor, anmalar ve adliye önünde basın açıklamaları yapılıyor. | Talepler: Aileler, kamu görevlileri hakkında verilen beraat ve düşük cezaların kaldırılmasını, bütün idari ve siyasi sorumluların etkili biçimde yargılanmasını ve cezasızlığın son bulmasını istiyor.', 'POINT', '[39.1773189, 27.64426]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_42', 'layer_direnis_cinayet', 'İliç Çöpler Altın Madeni İş Cinayeti Davası', 'Yer: İliç / Erzincan | Sendika/Kurum: İliç maden katliamında yakınlarını kaybeden aileler, avukatlar ve meslek örgütleri | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 13 Şubat 2024 tarihinden beri, 889. gün; dava 20 Ekim 2026’ya ertelendi | Eylem Biçimi: Duruşmalar takip ediliyor, adliye önünde açıklamalar ve dayanışma eylemleri yapılıyor. | Talepler: Aileler, Anagold ve Çalık Grubu yöneticileriyle bütün kamu görevlilerinin sorumlulukları oranında yargılanmasını, tutukluluk tedbirlerinin uygulanmasını, çevre ve işçi sağlığı suçlarının tüm yönleriyle ortaya çıkarılmasını istiyor.', 'POINT', '[39.4447136, 38.5341584]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_43', 'layer_direnis_kayip', '6 Şubat Deprem Davaları adalet mücadelesi', 'Yer: Depremden etkilenen kentler ve Türkiye geneli | Sendika/Kurum: Adalet Peşinde Aileleri Platformu ve depremde yakınlarını kaybeden aileler | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 6 Şubat 2023 tarihinden beri, 1261. gün | Eylem Biçimi: Duruşmalar izleniyor, adliye ve Adalet Bakanlığı önünde açıklamalar, anmalar, yürüyüşler ve imza kampanyaları düzenleniyor. | Talepler: Aileler, yapı müteahhitleriyle birlikte ruhsat, denetim ve imar sorumluluğu bulunan bütün kamu görevlilerinin yargılanmasını, olası kast hükümlerinin uygulanmasını ve etkili, adil yargılama yapılmasını istiyor.', 'POINT', '[39.9181421, 32.8521359]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_44', 'layer_direnis_ekoloji', 'Turnalar Yaylası maden direnişi', 'Yer: Turnalar Yaylası / Korgan / Ordu | Sendika/Kurum: Korgan Aybastı Kabataş Çevre Derneği, yöre halkı ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: Temmuz 2026’da yoğunlaşan yayla nöbeti; başlangıcın gün düzeyi doğrulanamadı | Eylem Biçimi: Yayla nöbeti tutuluyor, dayanışma çadırı kuruluyor, kitlesel açıklamalar ve dava takibi yapılıyor. | Talepler: Yöre halkı, Taşyapı’nın maden arama ve sondaj çalışmalarının durdurulmasını, su kaynaklarının, ormanların, meraların, tarım ve hayvancılığın korunmasını istiyor.', 'POINT', '[40.6665709, 37.2662116]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_45', 'layer_direnis_ekoloji', 'Arslanköy boksit madeni genişletmesine karşı mücadele', 'Yer: Arslanköy / Toroslar / Mersin | Sendika/Kurum: Arslanköy halkı, MERÇED ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 24 Aralık 2025 tarihinden beri, 209. gün | Eylem Biçimi: Halk toplantıları, basın açıklamaları, imza kampanyaları ve ÇED süreci takibi yapılıyor. | Talepler: Köylüler, boksit madeni sahasının 23 hektardan yaklaşık 510 hektara çıkarılmasının durdurulmasını, su kaynaklarının, meraların, tarımın, hayvancılığın ve yayla yaşamının korunmasını istiyor.', 'POINT', '[37.018568, 34.289681]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_46', 'layer_direnis_isci', 'Fugo Yer Hizmetleri Cem Çelik işe iade mücadelesi', 'Yer: İstanbul Havalimanı ve Gayrettepe / İstanbul | Sendika/Kurum: DİSK/Nakliyat-İş | İşkolu: Havacılık ve Yer Hizmetleri | Durum: Devam ediyor | Süre: 20 Temmuz 2026 tarihinden beri, 1. gün | Eylem Biçimi: Fugo Yer Hizmetleri şirket merkezi önünde basın açıklaması yapılıyor, işe iade ve sendikal özgürlük çağrısı gerçekleştiriliyor. | Talepler: Cem Çelik’in sendikaya üye olduğu için Kod 46 ile yapılan tazminatsız işten çıkarmasının geri alınması, işe iade edilmesi, sendikal baskıların ve ağır çalışma koşullarının son bulması isteniyor.', 'POINT', '[41.065865, 29.0035922]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_47', 'layer_direnis_isci', 'İBB memurlarının toplu sözleşme ve SDS mücadelesi', 'Yer: Saraçhane / İstanbul | Sendika/Kurum: İstanbul Büyükşehir Belediye Çalışanları Derneği ve Bem-Bir-Sen üyesi İBB memurları | İşkolu: Belediye Hizmetleri | Durum: Devam ediyor | Süre: 20 Ocak 2026 tarihinden beri, 182. gün. Talepler 18 Temmuz 2026’da yeniden gündeme getirildi. | Eylem Biçimi: Saraçhane’de basın açıklamaları ve protesto eylemleri yapılıyor, sosyal medya üzerinden hakların geri verilmesi çağrıları gerçekleştiriliyor. | Talepler: İBB’de bekleyen toplu sözleşmelerin imzalanması, Sosyal Denge Sözleşmesi ücretinin yükseltilmesi ve yüzde 120 net ödenmesi, kaldırılan Ramazan ve Kurban Bayramı ikramiyeleri, 1 Mayıs ikramiyesi ve yakacak yardımının geri verilmesi isteniyor.', 'POINT', '[41.013401, 28.9660522]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_48', 'layer_direnis_ekoloji', 'İnceğiz taş ocağına karşı yaşam alanı mücadelesi', 'Yer: İnceğiz Mahallesi, Gazipaşa / Antalya | Sendika/Kurum: İnceğiz Mahallesi halkı ve mahalle muhtarlığı | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 15 Temmuz 2026 tarihinden beri, 6. gün | Eylem Biçimi: Mahallede kitlesel eylem düzenleniyor, pankart ve dövizlerle basın açıklaması yapılıyor, ÇED kararına karşı hukuki süreç hazırlanıyor. | Talepler: İnceğiz halkı, kalker ocağı ve kırma-eleme tesisi projesinin iptal edilmesini, tarım alanlarının, içme ve sulama suyu kaynaklarının, ormanların, doğal yaşamın ve köyün üretim düzeninin korunmasını istiyor.', 'POINT', '[36.335211, 32.345413]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_49', 'layer_direnis_hapishane', 'Taceddin Erol Şahin’in tecride karşı açlık grevi', 'Yer: Marmara 6 No’lu L Tipi Hapishanesi / Silivri | Sendika/Kurum: Taceddin Erol Şahin, İstanbul Üniversitesi Öğrenci Meclisi ve dayanışma kurumları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 29 Nisan 2026 tarihinden beri. 20 Temmuz 2026 itibarıyla takvim hesabıyla 83. gün. Gün sayısı bazı açıklamalarda 73, 74 veya 77 olarak farklı aktarılıyor. | Eylem Biçimi: Süresiz ve dönüşümsüz açlık grevi sürdürülüyor, mektuplar ve açıklamalar yayımlanıyor, öğrenci örgütleri ve dayanışma kurumları tarafından eylem ve çağrılar yapılıyor. | Talepler: Taceddin Erol Şahin, ağır tecrit koşullarının, 24 saat kamera gözetiminin ve sosyal hak gasplarının son bulmasını, insani hapishane koşullarının sağlanmasını, hakkındaki davaların düşürülmesini ve serbest bırakılmasını istiyor.', 'POINT', '[41.0904287, 28.1520812]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_50', 'layer_direnis_ekoloji', 'Sallar Malê Sala GES karşıtı mücadele', 'Yer: Sallar, Malê Sala Mahallesi, Ergani / Diyarbakır | Sendika/Kurum: Sallar Mahallesi halkı ve ekoloji örgütleri | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 12 Temmuz 2026 tarihinden beri, 9. gün | Eylem Biçimi: Mahallede yürüyüş ve kitlesel basın açıklaması yapılıyor, yerel halk ve ekoloji örgütleri tarafından proje karşıtı çağrılar gerçekleştiriliyor. | Talepler: Sallar halkı, Smart GES Enerji Üretim AŞ tarafından yapılmak istenen Güneş Enerjisi Santrali projesinin iptal edilmesini, mera ve tarım alanlarının, hayvancılığın, geçim kaynaklarının ve yaşam alanlarının korunmasını istiyor.', 'POINT', '[38.270784, 39.677666]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_51', 'layer_direnis_ekoloji', 'Cennetpınarı taş ocağına karşı yaşam alanı mücadelesi', 'Yer: Cennetpınarı Mahallesi / Türkoğlu / Kahramanmaraş | Sendika/Kurum: Cennetpınarı Mahallesi halkı ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 22 Haziran 2026 tarihinden beri, 29. gün | Eylem Biçimi: Mahallede kitlesel basın açıklaması yapılıyor, sondaj çalışmalarına itiraz ediliyor, hukuki ve idari süreçler takip ediliyor. | Talepler: Cennetpınarı halkı, Med Restorasyon tarafından yapılmak istenen mermer ocağı projesinin ve sondaj çalışmalarının tamamen iptal edilmesini, tarım alanlarının, zeytinliklerin, su kaynaklarının, meraların, ormanların ve depremden etkilenen yerleşim alanlarının korunmasını istiyor.', 'POINT', '[37.3120499, 37.0075901]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_52', 'layer_direnis_ekoloji', 'Aslandere maden aramalarına karşı yaşam alanı mücadelesi', 'Yer: Aslandere Köyü / Fındıklı / Rize | Sendika/Kurum: Aslandere Köyü halkı, Viçe Çevre Meclisi ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 21 Temmuz 2025 tarihinden beri, 365. gün | Eylem Biçimi: Maden arama amacıyla bölgeye gelen şirket aracı durduruluyor, basın açıklamaları yapılıyor, yerel örgütlenme ve süreç takibi yürütülüyor. | Talepler: Aslandere halkı, maden arama ve saha inceleme çalışmalarının durdurulmasını, köyün ormanlarının, derelerinin, çay bahçelerinin, su kaynaklarının ve yaşam alanlarının korunmasını istiyor.', 'POINT', '[41.2706609, 41.140057]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_53', 'layer_direnis_ekoloji', 'Karakaya Köyü taş ocağına karşı yaşam alanı mücadelesi', 'Yer: Karakaya Köyü / Sungurlu / Çorum | Sendika/Kurum: Karakaya Köyü Taş Ocağı Platformu, Karakaya Köyü Yardımlaşma ve Dayanışma Derneği ve köy halkı | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 8 Ekim 2025 tarihinden beri, 286. gün | Eylem Biçimi: ÇED kararına karşı dava açılıyor, mahkeme ve bilirkişi süreçleri takip ediliyor, adliye önünde protestolar ve basın açıklamaları yapılıyor. | Talepler: Karakaya halkı, köyün yakınında yapılmak istenen taş ocağı ve kırma-eleme tesisinin iptal edilmesini, yeraltı sularının, tarım alanlarının, hayvancılığın, doğal yaşamın ve köy yerleşiminin korunmasını istiyor.', 'POINT', '[40.25614, 34.62701]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_54', 'layer_direnis_ekoloji', 'Gümüşhacıköy maden ruhsatlarına karşı mücadele', 'Yer: Gümüşhacıköy, İnegöl Dağı ve çevre köyler / Amasya | Sendika/Kurum: Gümüşhacıköy Çevre Platformu, köylüler ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 19 Nisan 2026 tarihinden beri, 93. gün | Eylem Biçimi: Basın açıklamaları yapılıyor, Öğretmenevi önünden Cumhuriyet Meydanı’na yürüyüş düzenleniyor, miting ve ruhsat iptal çağrıları gerçekleştiriliyor. | Talepler: Gümüşhacıköy halkı, İmirler, Karaali, Kılıçaslan ve Aşağıovacık köyleri ile İnegöl Dağı’nı kapsayan maden ihalelerinin ve ruhsatların iptal edilmesini, su kaynaklarının, göletlerin, meraların, ormanların, tarım alanlarının ve tarihi dokunun korunmasını istiyor.', 'POINT', '[40.873622, 35.2159369]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_55', 'layer_direnis_ekoloji', 'Havaçor Doğa ve Canlı Yaşam Nöbeti', 'Yer: Havaçor Köyü ve Havaçor Vadisi / Ovacık / Dersim | Sendika/Kurum: Havaçor Köyü Derneği, köylüler, yöre dernekleri ve ekoloji örgütleri | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 24 Mayıs 2026’da başlayan bir aylık nöbet tamamlandı. | Eylem Biçimi: Havaçor Vadisi’nde yaşam nöbeti tutuluyor, çadır kuruluyor, basın açıklamaları ve dayanışma çağrıları yapılıyor. | Talepler: Havaçor halkı, vadideki endemik bitkilerin ve yaban hayatının korunmasını, bitkilerin ticari amaçlarla kökünden sökülmesinin durdurulmasını, maden ve enerji projeleriyle yaşam alanlarının tahrip edilmesine son verilmesini istiyor.', 'POINT', '[39.357044, 39.216588]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_56', 'layer_direnis_ekoloji', 'Satıcılar Bazirgân GES karşıtı mücadele', 'Yer: Satıcılar, Bazirgân Köyü / Diyadin / Ağrı | Sendika/Kurum: Satıcılar Köyü halkı ve yaşam alanı savunucuları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 12 Nisan 2026 tarihinden beri, 100. gün | Eylem Biçimi: Köyde basın açıklamaları yapılıyor, iş makineleri durduruluyor, mera alanlarında bekleyiş sürdürülüyor, çadır nöbeti hazırlığı ve resmî başvurular yapılıyor. | Talepler: Satıcılar halkı, köyün ortak mera ve tarım alanlarına yapılmak istenen GES projesinin durdurulmasını, kurulan panellerin kaldırılmasını, meraların, tarımsal üretimin ve hayvancılığın korunmasını istiyor.', 'POINT', '[39.634093, 43.652441]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_57', 'layer_direnis_ekoloji', 'Yeşilalıç mera alanlarında GES karşıtı mücadele', 'Yer: Yeşilalıç Pagan Mahallesi / Saray / Van | Sendika/Kurum: Yeşilalıç Mahallesi halkı ve mahalle muhtarlığı | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 22 Mayıs 2026 tarihinden beri, 60. gün | Eylem Biçimi: Mera alanında protestolar yapılıyor, 500 imza toplanıyor, savcılık, kaymakamlık, valilik ve ilgili kamu kurumlarına başvurular gerçekleştiriliyor. | Talepler: Yeşilalıç halkı, 1400 dönümlük mera alanına yapılmak istenen GES projesinin durdurulmasını, hayvanların otlama alanlarının, meraların ve köyün temel geçim kaynağı olan hayvancılığın korunmasını istiyor.', 'POINT', '[38.4386, 44.0216]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_58', 'layer_direnis_ekoloji', 'Pülümür Karagöz Gurik krom ocağına karşı mücadele', 'Yer: Karagöz Gurik ve çevre köyler / Pülümür / Dersim | Sendika/Kurum: Karagöz ve Çevre Köyleri İnisiyatifi, Munzur Çevre Derneği, Dersim Barosu ve bölge halkı | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 18 Mart 2026 tarihinden beri, 125. gün | Eylem Biçimi: ÇED sürecine karşı hukuki başvurular yapılıyor, yaklaşık 2 bin imza toplanıyor, köy toplantıları, halk buluşmaları ve basın açıklamaları düzenleniyor. | Talepler: Bölge halkı, Dimin Madencilik tarafından yapılmak istenen krom ocağı projesinin ve ÇED sürecinin sonlandırılmasını, Hel Dağı’nın, meraların, kaynak sularının, endemik bitkilerin, yaban hayatının, arıcılık ve hayvancılık alanlarının korunmasını istiyor.', 'POINT', '[39.443907, 39.6818951]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_59', 'layer_direnis_isci', 'TYH Tekstil işçilerinin sendikal hak ve işe iade mücadelesi', 'Yer: Akhisar / Manisa, Alpullu / Kırklareli, Ordu ve Keşan / Edirne | Sendika/Kurum: DİSK/Tekstil | İşkolu: Tekstil | Durum: Devam ediyor | Süre: 13 Şubat 2026 tarihinden beri, 158. gün. İşçiler 24 Haziran ve 3 Temmuz 2026’da yeniden eylem yaptı. | Eylem Biçimi: Fabrika önlerinde ve vardiya girişlerinde basın açıklamaları, saatlik iş bırakma ve dayanışma eylemleri yapılıyor, işe iade davaları takip ediliyor. | Talepler: TYH Tekstil işçileri, ücretlerin zamanında ve eksiksiz ödenmesini, sendikal baskı ve mobbingin son bulmasını, işten çıkarılan sendika üyelerinin işe iade edilmesini, sendikal yetkinin tanınmasını ve toplu iş sözleşmesi sürecinin başlatılmasını istiyor.', 'POINT', '[38.8940105, 27.7387727]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_60', 'layer_direnis_isci', 'Bizden Giyim işçilerinin ücret ve tazminat mücadelesi', 'Yer: Kemalpaşa / İzmir | Sendika/Kurum: Bizden Giyim işçileri, Dev Tekstil ve Ege İşçi Birliği | İşkolu: Tekstil | Durum: Devam ediyor | Süre: 28 Haziran 2026’daki eylemden beri, 23. gün | Eylem Biçimi: Fabrika önünde basın açıklamaları ve protestolar yapılıyor, şirket yetkililerine ulaşılmaya çalışılıyor, hukuki süreç takip ediliyor. | Talepler: İşçiler, ödenmeyen ücretlerinin, kıdem ve ihbar tazminatlarının eksiksiz ödenmesini, işten çıkış işlemlerinin hukuka uygun biçimde yapılmasını ve patronun işçilere karşı sorumluluklarını yerine getirmesini istiyor.', 'POINT', '[38.437982, 27.266401]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_61', 'layer_direnis_isci', 'Van Büyükşehir Belediyesi işçilerinin işe iade direnişi', 'Yer: Van Büyükşehir Belediyesi ve Sanat Sokağı / Van | Sendika/Kurum: DİSK/Genel-İş ve işten çıkarılan belediye işçileri | İşkolu: Belediye Hizmetleri | Durum: Devam ediyor | Süre: 30 Temmuz 2025 tarihinden beri, takvim hesabıyla 356. gün | Eylem Biçimi: Sanat Sokağı’nda nöbet tutuluyor, belediye önünde açıklamalar, yürüyüşler ve dayanışma ziyaretleri yapılıyor, dava süreçleri takip ediliyor. | Talepler: İşçiler, kayyım yönetimi tarafından yapılan işten çıkarmaların geri alınmasını, 223 işçinin işe iade edilmesini, işe iade yönündeki mahkeme kararlarının uygulanmasını ve siyasi-sendikal ayrımcılığın son bulmasını istiyor.', 'POINT', '[38.4910134, 43.4038643]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_62', 'layer_direnis_isci', 'Torbalı Belediyesi işçilerinin ücret alacakları mücadelesi', 'Yer: Torbalı / İzmir | Sendika/Kurum: Belediye-İş İzmir 4 No’lu Şube ve BORBEL işçileri | İşkolu: Belediye Hizmetleri | Durum: Devam ediyor | Süre: 15 Temmuz 2026’da yarım günlük iş bırakma yapıldı. Görüşmeler ve alacak sorunu sürüyor. | Eylem Biçimi: Temizlik işçileri yarım gün iş bırakıyor, belediye binası önünde basın açıklaması ve protesto yapılıyor. | Talepler: İşçiler, eksik ve gecikmeli ödenen ücretlerinin, ikramiyelerinin ve toplu sözleşmeden doğan ücret farklarının eksiksiz ödenmesini, ücretlerin düzenli yatırılmasını istiyor.', 'POINT', '[38.153703, 27.356817]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_63', 'layer_direnis_isci', 'Kakil Yazar ve Turan Aktaş işe iade direnişi', 'Yer: Şişli Belediyesi / İstanbul | Sendika/Kurum: Kentyol AŞ işçileri Kakil Yazar ve Turan Aktaş, dayanışma kurumları | İşkolu: Belediye Hizmetleri | Durum: Devam ediyor | Süre: Kasım 2019’dan beri, 2.430 günü aşkın süredir devam ediyor. | Eylem Biçimi: Şişli Belediyesi önünde oturma eylemi ve basın açıklamaları yapılıyor, CHP İstanbul İl Başkanlığı ve CHP Genel Merkezi önünde eylemler düzenleniyor, dayanışma ziyaretleri gerçekleştiriliyor. | Talepler: Kakil Yazar ve Turan Aktaş, hukuksuz işten çıkarmaların geri alınmasını, kesinleşen mahkeme kararlarının uygulanmasını, işlerine iade edilmelerini ve belediyelerdeki işten çıkarma politikalarının son bulmasını istiyor.', 'POINT', '[41.0642751, 28.9832604]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_64', 'layer_direnis_isci', 'İzmir Büyükşehir Belediyesi kadrolu işçilerinin toplu sözleşme mücadelesi', 'Yer: İzmir Büyükşehir Belediyesi hizmet birimleri / İzmir | Sendika/Kurum: Belediye-İş İzmir 2 No’lu Şube | İşkolu: Belediye Hizmetleri | Durum: Devam ediyor | Süre: 15 Haziran 2026 tarihinden beri, 36. gün. Grev kararı 25 Haziran 2026’da asıldı. | Eylem Biçimi: Belediye birimleri önünde basın açıklamaları yapılıyor, toplu yürüyüşler düzenleniyor ve işyerlerine grev kararı asılıyor. | Talepler: İşçiler, 2026–2028 toplu iş sözleşmesinin talepleri doğrultusunda imzalanmasını, ücret ve sosyal hakların iyileştirilmesini, pazar gününün hafta tatili olarak korunmasını ve kazanılmış hakların geri alınmamasını istiyor.', 'POINT', '[38.4251436, 27.1442423]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
INSERT INTO Feature (id, layerId, title, description, type, coordinates, createdAt, updatedAt) VALUES ('direnis_feat_65', 'layer_direnis_hapishane', 'Ekim Polat’ın tedavi hakkı için Songül İlker’in oturma eylemi', 'Yer: İstanbul ve Burdur Yüksek Güvenlikli Hapishanesi | Sendika/Kurum: Songül İlker, İHD İstanbul Şubesi Hapishane Komisyonu ve dayanışma kurumları | İşkolu: Bağımsız | Durum: Devam ediyor | Süre: 11 Ağustos 2022 tarihinden beri sürüyor. Güncel paylaşımda oturma eyleminin 1398. gününde olduğu belirtildi. | Eylem Biçimi: İlk olarak Denizli T Tipi Hapishanesi önünde oturma eylemi başlatıldı. Eylem daha sonra İHD İstanbul Şubesine taşındı. Oturma eylemleri, basın açıklamaları, sosyal medya çalışmaları ve İHD’nin F Oturmalarıyla tedavi ve tahliye çağrıları sürdürülüyor. | Talepler: Songül İlker, akromegali hastası Ekim Polat’ın hastaneye yatırılarak insani koşullarda tedavi edilmesini, gerekli ameliyat ve tetkiklerin yapılmasını, sağlık ve yaşam hakkına yönelik engellerin kaldırılmasını, kötü muamele ve tehditlerin son bulmasını ve ağır hastalığı nedeniyle serbest bırakılmasını istiyor.', 'POINT', '[41.0800249, 29.0104397]', NOW(), NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), coordinates=VALUES(coordinates), updatedAt=NOW();
